// 1. Extract the raw question (or default to empty string)
const rawQuestion = $json.question || '';

// 2. Validate & Clean: Remove extra spaces, and strictly limit to 500 chars.
const cleanQuestion = rawQuestion.trim().slice(0, 500);

// 3. Define the Persona (System Prompt)
const systemPrompt = "You are a patient guide to the Gita. Keep answers under 100 words.";

// 4. Assemble the exact JSON structure the API expects
const messages = [
  { role: 'system', content: systemPrompt },
  { role: 'user', content: cleanQuestion }
];

// 5. Output the cleaned data and the assembled array
return [{
  json: {
    ...$json,
    messages,
    inputLength: cleanQuestion.length
  }
}];
